# Ada Health Symptom Checker
import requests

ADA_API_KEY = "3904d24a08aa08f6a68dc338f9be277e"
BASE_URL = "https://api.ada.com/v1"

def start_assessment(symptoms, age, gender):
    """Start symptom assessment"""
    response = requests.post(
        f"{BASE_URL}/assessments",
        headers={"Authorization": f"Bearer {ADA_API_KEY}"},
        json={
            "symptoms": symptoms,
            "demographics": {
                "age": age,
                "gender": gender
            }
        }
    )
    return response.json()

def get_assessment_results(assessment_id):
    """Get results from symptom assessment"""
    response = requests.get(
        f"{BASE_URL}/assessments/{assessment_id}",
        headers={"Authorization": f"Bearer {ADA_API_KEY}"}
    )
    return response.json()
